import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { PartyService } from '../../services/party-service';
import { party } from '../party/party';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { Product } from '../../models/invoice';
import { ProductService } from '../../services/product-service';

@Component({
  selector: 'app-product-master',
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './product-master.html',
  styleUrl: './product-master.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ProductMaster {
  
  Product: Product[] = [];
  searchTerm = '';

  constructor(private service: ProductService, private cd: ChangeDetectorRef) {}

  ngOnInit() {
    this.service.getAllProducts().subscribe({
      next: (data) => {
        this.Product = data;
         this.cd.markForCheck();
        console.log("Products from backend:", this.Product);
      },
      error: (err) => console.error("Error fetching parties:", err)
    });
  }

  filteredProducts() {
    const term = this.searchTerm.toLowerCase();
    return this.Product.filter(p =>
      p.productName.toLowerCase().includes(term) ||
      p.catagoryName.toLowerCase().includes(term) ||
      p.companyName.toLowerCase().includes(term) ||
      p.productPrice.toPrecision().includes(term) 
    );
  }

}
